import { ReasoningTrace } from "@/components/design-for-ai/ai-reasoning-trace";

// Your model drives it: append each step as it reasons, and each word of the reply as it streams.
export default function Reply({ status, startedAt, steps, reply, thoughtForMs }) {
  return (
    <ReasoningTrace
      state={status} // "thinking" | "answering" | "done"
      startedAt={startedAt} // Date.now() when thinking began. Starts the live timer.
      trace={steps} // [{ summary: "Checking the billing rule", detail: "Seats are prorated by day.", atMs: 600 }]
      answer={reply} // ["The jump is proration, not a double charge."]
      thoughtForMs={thoughtForMs} // optional final time in ms. Without it the measured time is kept.
    />
  );
}

// The reader's open or closed choice holds across runs (rememberChoice, default true).
// Pass storageKey="reasoning-trace" to keep it across reloads, or open and onOpenChange to own it yourself.
